const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const Score = yield* Database.resolve('dxn:com.example.operation.score');
const tasks = yield* Database.query(Filter.type(Task, { status: 'open' })).run;
yield* print('open count', tasks.length);
const results = [];
for (const t of tasks) {
  const r = yield* Operation.invoke(Score, { title: t.title });
  results.push({ id: t.id, title: t.title, score: r });
}
yield* print('raw results', results);

